'https://wdown.ebsi.co.kr/W61001/01exam/20200722/go3/mathb_mun_726D5QM2.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200618/go3/matha_mun_855P2J69.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200618/go3/mathb_mun_7D699Z73.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200512/go3/matha_mun_6ZI8294B.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200512/go3/mathb_mun_RQ23N417.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200312/go3/matha_mun_2A8W17W6.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20200312/go3/mathb_mun_IDI8L2GX.pdf',
'https://wdown.ebsi.co.kr/W61001/01exam/20261119/go3/live_main_paper_1_math_K63RYJL3.pdf', 'https://wdown.ebsi.co.kr/W61001/01exam/20261119/go3/live_main_paper_2_math_F51864J3.pdf')) or coalesce(v->>'pdf_page','') !~ '^([1-9]|[1-3][0-9]|40)$' then return false; end if;
  if jsonb_typeof(v->'crop') is distinct from 'array' then return false; end if;
  if jsonb_array_length(v->'crop')<>4 then return false; end if;
  for p in select value from jsonb_array_elements(v->'crop') loop if jsonb_typeof(p) is distinct from 'number' or p::numeric<0 or p::numeric>1 then return false; end if; end loop;
  if (v->'crop'->>0)::numeric >= (v->'crop'->>2)::numeric or (v->'crop'->>1)::numeric >= (v->'crop'->>3)::numeric then return false; end if;
  if exists(select 1 from jsonb_object_keys(v) k where k not in ('kind','official_url','pdf_page','crop','image_key','image_path')) then return false; end if;
  if v ? 'image_key' or v ? 'image_path' then
   if jsonb_typeof(v->'image_key') is distinct from 'string' or char_length(v->>'image_key') not between 1 and 160 or jsonb_typeof(v->'image_path') is distinct from 'string' or (v->>'image_path') !~ '^/exam-images/q-[a-f0-9]{24}[.]webp$' then return false; end if;
  end if;
 elsif exists(select 1 from jsonb_object_keys(v) k where k<>'kind') then return false;
 end if;
 if jsonb_typeof(d->'strokes') is distinct from 'array' then return false; end if;
 if jsonb_array_length(d->'strokes')<1 or jsonb_array_length(d->'strokes')>500 then return false; end if;
 for s in select value from jsonb_array_elements(d->'strokes') loop
  if jsonb_typeof(s) is distinct from 'object' or not(s ?& array['color','size','points']) then return false; end if;
  if exists(select 1 from jsonb_object_keys(s) k where k not in ('color','size','points')) then return false; end if;
  if coalesce(s->>'color','') not in ('#151713','#2456d6','#d63232','#16844a') or jsonb_typeof(s->'size') is distinct from 'number' then return false; end if;
  if (s->>'size')::numeric<1 or (s->>'size')::numeric>12 or jsonb_typeof(s->'points') is distinct from 'array' then return false; end if;
  if jsonb_array_length(s->'points')<1 then return false; end if;
  total:=total+jsonb_array_length(s->'points');if total>15000 then return false; end if;
  for p in select value from jsonb_array_elements(s->'points') loop
   if jsonb_typeof(p) is distinct from 'array' then return false; end if;
   if jsonb_array_length(p)<>2 or jsonb_typeof(p->0) is distinct from 'number' or jsonb_typeof(p->1) is distinct from 'number' then return false; end if;
   if (p->>0)::numeric<0 or (p->>0)::numeric>1000 or (p->>1)::numeric<0 or (p->>1)::numeric>h then return false; end if;
  end loop;
 end loop;
 return true;
exception when others then return false;
end $function$
;
CREATE OR REPLACE FUNCTION public.page_official_exam_catalog(p_filters jsonb, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with filtered as materialized (
    select p.id, p.title, p.grade, p.subject, p.unit, p.source, p.exam_question_id,
      p.source_details->'classification' as classification,
      coalesce(nullif(d.level, 'basic'), 'unclassified') as difficulty,
      s.id as session_id, s.calendar_year, s.month, s.provider, q.section, q.question_no, q.variant
    from public.exam_sessions s
    join public.exam_questions q on q.session_id = s.id
    join public.problems p on p.exam_question_id = q.id
    left join public.problem_difficulties d on d.problem_id = p.id
    where p.public and not p.withdrawn and q.variant <> 'even'
      and (p_filters->>'examSource' is null or s.provider = p_filters->>'examSource')
      and (p_filters->>'grade' is null or p.grade = p_filters->>'grade')
      and (p_filters->>'year' is null or s.calendar_year::text = p_filters->>'year')
      and (p_filters->>'month' is null or s.month::text = p_filters->>'month')
      and (p_filters->>'variant' is null or q.variant = p_filters->>'variant')
      and (p_filters->>'difficulty' is null or coalesce(nullif(d.level,'basic'),'unclassified') = p_filters->>'difficulty')
      and p_filters->>'paper' is null
      and (p_filters->>'review' is null
        or (p_filters->>'review' = 'review' and p.source_details->'classification'->>'needs_review' = 'true')
        or (p_filters->>'review' = 'manual' and p.source_details->'classification'->>'method' = 'manual'))
      and (p_filters->>'subject' is null or p.subject = p_filters->>'subject'
        or (p_filters->>'related' = 'true' and (p.source_details->'classification'->'related_unit_keys')
          ?| array(select jsonb_array_elements_text(coalesce(p_filters->'relatedSubjectKeys','[]'::jsonb)))))
      and (p_filters->>'unit' is null or p.source_details->'classification'->>'unit_key' = p_filters->>'unit'
        or (p_filters->>'related' = 'true' and (p.source_details->'classification'->'related_unit_keys') ? (p_filters->>'unit')))
      and (p_filters->>'q' is null or pg_catalog.strpos(lower(concat_ws(' ', p.title, p.subject, p.unit,
        p.source_details->>'label', p.source_details->'classification'->'evidence')), lower(left(p_filters->>'q', 80))) > 0)
  ), page as (
    select *,
      row_number() over (order by calendar_year desc, month desc, grade collate "C",
        case provider when 'kice' then 0 else 1 end,
        array_position(array['common','math','math-a','math-b','math-a-integral','math-a-probability','math-a-discrete','type-a','type-b','humanities','natural','arts','probability','calculus','geometry']::text[], section),
        question_no, id) as position
    from filtered
    order by position
    limit 24 offset greatest(coalesce(p_offset,0),0)
  )
  select jsonb_build_object(
    'total', case when coalesce(p_offset,0) <= 0 then (select count(*) from filtered) end,
    'sessions', case when coalesce(p_offset,0) <= 0 then (
      select coalesce(jsonb_agg(jsonb_build_object('calendar_year',calendar_year,'month',month,'grade',grade,'provider',provider)), '[]'::jsonb)
      from public.exam_sessions) end,
    'rows', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', a.id, 'title', a.title, 'grade', a.grade, 'subject', a.subject, 'unit', a.unit, 'source', a.source,
        'exam_question_id', a.exam_question_id, 'classification', a.classification, 'difficulty', a.difficulty,
        'solution_problem_id', coalesce(
          (select a.id where exists(select 1 from public.solutions sol where sol.problem_id=a.id and sol.public)),
          (select p.id from public.exam_questions q join public.problems p on p.exam_question_id=q.id
            where a.variant='odd' and q.session_id=a.session_id and q.variant='even' and q.section=a.section
              and q.question_no=a.question_no and p.public and not p.withdrawn
              and exists(select 1 from public.solutions sol where sol.problem_id=p.id and sol.public))
        )
      ) order by a.position), '[]'::jsonb)
      from page a)
  );
$function$
;

