04,"ca42dd642dfe38ac63c85bea",1250,1361,null,null],[22,6,0.4984,0.41975,0.91,0.72211,"3fe2da563bf9a121e4a22123",1250,1261,null,null],[23,7,0.075,0.11098,0.4964,0.38975,"409d67795b75ef82561d7131",1250,1135,null,null],[24,7,0.075,0.55636,0.4964,0.86542,"bc58a08cca915b03dd51275d",1250,1258,null,null],[25,7,0.5084,0.17681,0.91,0.22954,"3e93f0e56951b650945ea103",1250,225,null,null],[26,7,0.5084,0.54937,0.91,0.60385,"ffddeca6de23af43da270445",1250,233,null,null],[27,8,0.075,0.08477,0.5024,0.13836,"a023a58d08d5b5c5d6294112",1250,215,null,null],[28,8,0.075,0.48587,0.5024,0.53102,"0364a2cc3b536813589fdf1a",1250,181,null,null],[29,8,0.5144,0.08477,0.91,0.22225,"433019eeabe1d4102921ad42",1250,597,null,null],[30,8,0.5144,0.48791,0.91,0.73027,"5d23d607d2ef1b59a0c031cf",1250,1052,null,null]]]
]$papers$::jsonb) p
), records as (
 select p.*,(q->>0)::integer as number,(q->>1)::integer as page,
  jsonb_build_array(q->2,q->3,q->4,q->5) as crop,'/exam-images/q-'||(q->>6)||'.webp' as asset,
  (q->>7)::integer as width,(q->>8)::integer as height,(q->>9)::numeric as rate,q->>10 as level
 from papers p cross join lateral jsonb_array_elements(questions) q
), classified as (
 select r.*, md5('archive-question:'||sid||':'||section||':'||variant||':'||number)::uuid as id,
  jsonb_build_object('calendar_year',year,'month',month,'grade',grade,'provider',provider,'section',section,'variant',variant,
   'question_no',number,'needs_review',true,'method','official_archive') as classification
 from records r
)
select id,sid::uuid,grade,section,variant,number,page,crop,asset,width,height,title||' '||number||'번'||case when form<>'' then ' · '||form else '' end as title,
 source,curriculum,classification,url,label,board,publisher,rate,level,rate_source,
 (case section when 'math-a' then '수학 가형' when 'math-b' then '수학 나형' when 'type-a' then '수학 A형' when 'type-b' then '수학 B형'
      when 'natural' then '수리 자연계' when 'humanities' then '수리 인문계' when 'arts' then '수리 예체능계'
      when 'math-a-integral' then '미분과 적분' when 'math-a-probability' then '확률과 통계' when 'math-a-discrete' then '이산수학' else '수학' end) as subject
from classified;

insert into public.exam_questions(id,session_id,variant,section,question_no,official_url,pdf_start_page,pdf_page,crop,classification,asset_path,width,height)
select id,sid,variant,section,number,url,1,page,crop,classification,asset,width,height from historical_2001_2019
on conflict(id) do nothing;
alter table public.problems disable trigger problems_rate;
alter table public.problems disable trigger problems_reward;
insert into public.problems(id,owner_id,exam_question_id,title,question,grade,subject,unit,curriculum_id,source,source_details,public,rights_confirmed)
select id,null,id,title,'공식 기출 수학 문제입니다.',grade,subject,'미분류',curriculum,source,
 jsonb_build_object('label',label,'board_url',board,'official_url',url,'pdf_page',page,'pdf_start_page',1,'crop',crop,
  'provider_name',publisher,'classification',classification,'asset_path',asset,'width',width,'height',height,'reference_only',true),
 true,true from historical_2001_2019
on conflict(id) do nothing;
alter table public.problems enable trigger problems_rate;
alter table public.problems enable trigger problems_reward;
insert into public.problem_difficulties(problem_id,level,classification_method,correct_rate,rate_basis,source_url,source_exam_seq,rate_collected_at,rule_version)
select id,level,'correct_rate',rate,rate_source->>3,rate_source->>0,(rate_source->>1)::int,(rate_source->>2)::timestamptz,
 'megastudy-20-50-80-v1'
from historical_2001_2019 where rate is not null
on conflict(problem_id) do nothing;

do $$begin
 if (select count(*) from historical_2001_2019 h
  join public.exam_questions q on q.id=h.id and q.session_id=h.sid and q.section=h.section
   and q.variant=h.variant and q.question_no=h.number and q.pdf_page=h.page and q.crop=h.crop and q.asset_path=h.asset
  join public.problems p on p.exam_question_id=q.id and p.public and p.source_details->>'asset_path'=h.asset) <> 9670
 then raise exception 'Historical questions are incomplete'; end if;
 if exists(select 1 from historical_2001_2019 h where h.rate is not null and not exists (
   select 1 from public.problem_difficulties d where d.problem_id=h.id and
    (d.classification_method='manual' or (d.correct_rate=h.rate and d.level=h.level and d.rate_basis=h.rate_source->>3))))
 then raise exception 'Historical rates are incomplete'; end if;
end$$;
notify pgrst, 'reload schema';
commit;
